\documentclass{article}
\usepackage[paperwidth=594mm,paperheight=841mm,margin=0mm]{geometry}
\usepackage{tcolorbox}
\tcbuselibrary{poster,skins,fitting}
\usepackage{graphicx}
\usepackage{amsmath,amssymb}
\usepackage{enumitem}
\usepackage[table]{xcolor}
\usepackage{lmodern}
\usepackage[T1]{fontenc}
\usepackage{pgfplots}
\pgfplotsset{compat=1.18}
\pagestyle{empty}

% ── Dark Theme Venue Colors ──
\definecolor{primary}{HTML}{020617}     % Slate 950 (Deep background)
\definecolor{secondary}{HTML}{DC2626}   % Red (Urgency)
\definecolor{accent}{HTML}{F59E0B}      % Amber (Hope)
\definecolor{bgposter}{HTML}{0F172A}    % Slate 900 (Poster background)

% Card Tints
\definecolor{redbg}{HTML}{450A0A}       % Deep red
\definecolor{bluebg}{HTML}{172554}      % Deep blue
\definecolor{darkbg}{HTML}{1E293B}      % Slate 800

% Card Title Bars
\definecolor{redtitlebg}{HTML}{7F1D1D}
\definecolor{bluetitlebg}{HTML}{1E3A8A}
\definecolor{darktitlebg}{HTML}{334155}

% Text Colors
\definecolor{textdark}{HTML}{F8FAFC}    % Light text for dark mode
\definecolor{textgray}{HTML}{94A3B8}    % Gray text
\definecolor{stathighlight}{HTML}{111827}

\pagecolor{bgposter}
\color{textdark}

% ── List styling ──
\setlist[itemize]{leftmargin=24pt, itemsep=12pt, parsep=4pt, topsep=6pt,
  label={\color{accent}$\blacktriangleright$}}
\setlist[enumerate]{leftmargin=24pt, itemsep=12pt, parsep=4pt, topsep=6pt,
  label={\color{secondary}\bfseries\arabic*.}}

% ── Figure+caption macro ──
\newcommand{\posterfig}[3]{%
  \centering\includegraphics[width=#1\linewidth]{#2}\\[3mm]
  {\fontsize{26}{32}\selectfont\color{textgray}\textit{#3}}\vspace{2mm}%
}

% ── Card styles (dark mode adapted) ──
\tcbset{
  redcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=redbg,
    borderline west={8pt}{0pt}{secondary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=redtitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.6, shadow xshift=6pt, shadow yshift=-6pt},
  },
  bluecard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=bluebg,
    borderline west={8pt}{0pt}{accent},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=bluetitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.6, shadow xshift=6pt, shadow yshift=-6pt},
  },
  darkcard/.style={
    enhanced, arc=4pt, boxrule=0pt, colback=darkbg,
    borderline west={8pt}{0pt}{primary},
    left=24pt, right=24pt, top=16pt, bottom=16pt,
    fonttitle=\fontsize{44}{52}\selectfont\bfseries\color{white},
    coltitle=white, colbacktitle=darktitlebg,
    toptitle=12pt, bottomtitle=12pt,
    titlerule=0pt,
    valign=top, drop shadow={opacity=0.6, shadow xshift=6pt, shadow yshift=-6pt},
  },
}

\begin{document}
\begin{tcbposter}[
  coverage={spread},
  poster={columns=2, rows=20, spacing=6mm},
]

% ══ TITLE BAR ══
\posterbox[
  enhanced, colback=primary, colframe=primary, colupper=textdark,
  arc=0pt, boxrule=0pt,
  left=30pt, right=30pt, top=16pt, bottom=8pt,
  halign=center, valign=center,
  drop shadow={opacity=0.5}
]{name=title, column=1, span=2, between=top and row3}{
  {\fontsize{72}{86}\selectfont\bfseries MALARIA: A PREVENTABLE KILLER}\\[16pt]
  {\fontsize{42}{52}\selectfont\color{accent} Global Progress and the Road Ahead}\\[12pt]
  {\fontsize{28}{36}\selectfont\color{textgray} Over half a million people still die each year, yet humanity has eliminated the disease from half the world.}
}

% ══ STATS BANNER ══
\posterbox[
  enhanced, colback=secondary, boxrule=0pt, arc=0pt,
  left=12pt, right=12pt, top=12pt, bottom=12pt,
  valign=center, halign=center,
  drop shadow={opacity=0.5}
]{name=stats, column=1, span=2, between=row3 and row6}{
  {\fontsize{130}{140}\selectfont\bfseries\color{white} 1,320 CHILDREN}\\[6pt]
  {\fontsize{64}{76}\selectfont\bfseries\color{white!90} LOSE THEIR LIVES EVERY SINGLE DAY}\\[12pt]
  {\fontsize{34}{44}\selectfont\color{white!80} to a disease we know exactly how to prevent and treat.}
}

% ══ COL 1: DEATH TRENDS ══
\posterbox[bluecard, title={Death Toll Trends: 2000--2023}
]{name=trends, column=1, between=row6 and row14}{
  \fontsize{30}{40}\selectfont
  Malaria deaths steadily declined from 2000 to 2015, but progress has stalled. Disruptions during the 2020 COVID-19 pandemic caused a significant setback.

  \vspace{8mm}
  \begin{center}
  \begin{tikzpicture}
  \begin{axis}[
      width=0.98\linewidth, height=130mm,
      axis lines=left,
      enlarge x limits=0.05,
      ymin=450, ymax=950,
      ytick={500,600,700,800,900},
      xtick={2000,2005,2010,2015,2020,2023},
      xticklabels={2000,2005,2010,2015,2020,2023},
      ylabel={Annual Deaths (Thousands)},
      ylabel style={font=\fontsize{26}{32}\selectfont\color{white!80}, yshift=8pt},
      tick label style={font=\fontsize{22}{28}\selectfont\color{white!80}},
      axis line style={white!40, thick},
      ymajorgrids=true,
      grid style={white!15, dashed},
      colors=white,
      clip=false
  ]
  \addplot[color=accent, ultra thick, mark=*, mark size=5pt] coordinates {
      (2000, 839)
      (2005, 755)
      (2010, 642)
      (2015, 562)
      (2019, 568)
      (2020, 625)
      (2023, 608)
  };
  \node[text=white, anchor=south west] at (axis cs:2015.5, 570) {\fontsize{22}{28}\selectfont Progress Stalls};
  \node[text=white, anchor=south east] at (axis cs:2019.5, 635) {\fontsize{22}{28}\selectfont COVID-19};
  \end{axis}
  \end{tikzpicture}
  \end{center}
}

% ══ COL 1: BURDEN ══
\posterbox[darkcard, title={The Burden: Who Malaria Kills}
]{name=burden, column=1, between=row14 and bottom}{
  \fontsize{32}{42}\selectfont
  \vspace{6mm}
  \begin{itemize}
    \item \textbf{>500,000 deaths} annually (2010s average).
    \item \textbf{Children under 5} are the most vulnerable, accounting for the highest share of fatalities.
    \item \textbf{Sub-Saharan Africa} bears the overwhelming majority of the global burden.
    \item \textbf{\textit{Plasmodium falciparum}} is the deadliest parasite species affecting humans.
  \end{itemize}
  \vspace{6mm}
  \colorbox{primary!50!black}{\parbox{0.94\linewidth}{%
    \vspace{8pt}
    \centering\fontsize{30}{38}\selectfont
    \color{textdark}\textbf{Key Context}: Although IHME and WHO estimates differ slightly, both confirm that Africa accounts for the vast majority of deaths---and has achieved the most progress.
    \vspace{8pt}
  }}
}

% ══ COL 2: HISTORICAL PROGRESS ══
\posterbox[redcard, title={From Half the World to a Quarter}
]{name=progress, column=2, between=row6 and row14}{
  \fontsize{30}{40}\selectfont
  Malaria is not inherently a "tropical disease." It was once endemic across roughly 50\% of the world's land surface, including Europe and North America (contracted by historical figures like Abraham Lincoln).

  \vspace{12mm}
  \begin{center}
  \fcolorbox{white!10}{redbg!50!black}{\parbox{0.44\linewidth}{%
    \centering\vspace{16mm}%
    {\fontsize{110}{120}\selectfont\bfseries\color{secondary} \textasciitilde50\%}\\[12mm]
    {\fontsize{34}{44}\selectfont\bfseries\color{textdark} Historic Risk}\\[6mm]
    {\fontsize{26}{32}\selectfont\color{white!70} Of global land surface\\[4mm] (\textasciitilde 1900)}\vspace{16mm}%
  }}%
  \hfill
  \fcolorbox{white!10}{bluebg!50!black}{\parbox{0.44\linewidth}{%
    \centering\vspace{16mm}%
    {\fontsize{110}{120}\selectfont\bfseries\color{accent} \textasciitilde27\%}\\[12mm]
    {\fontsize{34}{44}\selectfont\bfseries\color{textdark} Current Risk}\\[6mm]
    {\fontsize{26}{32}\selectfont\color{white!70} Of global land surface\\[4mm] (By 2002)}\vspace{16mm}%
  }}
  \end{center}
  \vspace{12mm}

  By 2002, the disease was eliminated from Europe, East Asia, Australia, and large parts of the Americas.
}

% ══ COL 2: WHAT WORKS ══
\posterbox[darkcard, title={What Works: Tools to Beat Malaria}
]{name=tools, column=2, between=row14 and bottom}{
  \fontsize{32}{42}\selectfont
  The same interventions that eliminated malaria from wealthy regions can be scaled globally:

  \vspace{10mm}
  \begin{itemize}[itemsep=20pt]
    \item \textbf{Insecticide-Treated Bednets} $\Rightarrow$ One of the most cost-effective tools, preventing mosquito bites during sleep.
    \item \textbf{Vaccines} $\Rightarrow$ New malaria vaccines offer a promising additional layer of protection for children.
    \item \textbf{Economic Development} $\Rightarrow$ Improved infrastructure, healthcare access, and better housing directly reduce transmission rates.
  \end{itemize}
}

\end{tcbposter}
\end{document}
EOF
